SELECT r.id FROM public.zsl_round r WHERE r.id=$1 AND (SELECT count(*) FROM zc_private.zsl_tournament_level_state WHERE id_round=$1 AND timeslot=2 AND id_level IS NOT NULL AND closed)=$2 AND NOT EXISTS(SELECT 1 FROM zc_private.zsl_tournament_level_state WHERE id_round=$1 AND timeslot=2 AND NOT closed) AND NOT EXISTS(SELECT 1 FROM zc_private.zsl_provisional_level_result p JOIN public.zsl_level l ON l.id=p.id_level WHERE l.id_round=$1 AND NOT p.finalised) FOR UPDATE
